/* === Section 6: Показатели проекта (16 индикаторов) — v1.0.2 === */
/* Структура: скрытый checkbox → label с основной строкой → panel с вложенной таблицей.
   Нативный клик по ▼ (через <label for="...">) — без JS. */

table.tbl-indicators {
    table-layout: fixed;
    width: 100%;
    border-collapse: collapse;
}
table.tbl-indicators th,
table.tbl-indicators td {
    border: 1px solid #cbd5e1;
    padding: 6px 8px;
    text-align: left;
    vertical-align: middle;
}
table.tbl-indicators th {
    background: #f1f5f9;
    font-weight: 600;
}
table.tbl-indicators col.col-num { width: 60px; }
table.tbl-indicators col.col-name { width: 40%; }
table.tbl-indicators col.col-result { width: calc(60% - 130px); word-wrap: break-word; }
table.tbl-indicators col.col-details { width: 70px; }

table.tbl-indicators td {
    word-wrap: break-word;
    overflow-wrap: break-word;
    vertical-align: middle;
}

/* Подкраска строк по severity (применяется на <tr> главной таблицы) */
table.tbl-indicators tr[data-status="critical"] {
    background: #fee2e2;  /* красный */
}
table.tbl-indicators tr[data-status="substantial"] {
    background: #fef3c7;  /* жёлтый */
}
table.tbl-indicators tr[data-status="informational"] {
    background: #dbeafe;  /* голубой */
}
table.tbl-indicators tr[data-status="normal"] {
    background: #ffffff;  /* без подкраски */
}

/* Колонка "Детали" — кликабельный треугольник (▼) */
table.tbl-indicators td.col-details {
    text-align: center;
    padding: 8px;
    width: 70px;
    font-weight: 700;
    color: #475569;
}

/* Маркер ▼ в колонке "Детали" */
.col-details-marker {
    display: inline-block;
    font-size: 16px;
    line-height: 1;
    color: #475569;
}

/* === v1.0.2: новая структура === */

/* Скрытый checkbox — переключатель видимости панели */
input.indicator-toggle {
    display: none;
}

/* Label оборачивает мини-таблицу — кликабельный по всей строке индикатора.
   Убираем подсветку при наведении/фокусе — выглядит как обычная строка. */
label.indicator-label {
    display: block;
    cursor: pointer;
    margin: 0;
}
label.indicator-label > table.tbl-indicators {
    margin: 0;
}
/* В label не должно быть outline (фокус-прячем — кликаем по самой строке) */
label.indicator-label:focus { outline: none; }
label.indicator-label:hover .col-details-marker { color: #0284c7; }

/* Когда checkbox НЕ отмечен — панель скрыта */
input.indicator-toggle:not(:checked) ~ .indicator-details-panel {
    display: none;
}
/* Когда checkbox отмечен — панель видна */
input.indicator-toggle:checked ~ .indicator-details-panel {
    display: block;
    padding: 0 40px 12px;
    background: #fafafa;
    border-bottom: 1px solid #e2e8f0;
}

/* Маркер меняется на ▲ при раскрытии */
input.indicator-toggle:checked ~ label.indicator-label .col-details-marker::before {
    content: '▲';
}
input.indicator-toggle:not(:checked) ~ label.indicator-label .col-details-marker::before {
    content: '▼';
}
/* Скрываем оригинальный символ ▼/▲ (мы используем ::before) */
input.indicator-toggle:checked ~ label.indicator-label .col-details-marker,
input.indicator-toggle:not(:checked) ~ label.indicator-label .col-details-marker {
    font-size: 0;  /* убираем оригинальный ▼ */
}
input.indicator-toggle:checked ~ label.indicator-label .col-details-marker::before,
input.indicator-toggle:not(:checked) ~ label.indicator-label .col-details-marker::before {
    font-size: 16px;  /* показываем псевдоэлемент */
}

/* Вложенная таблица (3 уровень) */
table.tbl-nested {
    width: 100%;
    border-collapse: collapse;
    margin-top: 8px;
}
table.tbl-nested th {
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    padding: 4px 6px;
    font-weight: 600;
    font-size: 12px;
    text-align: left;
}
table.tbl-nested td {
    border: 1px solid #e2e8f0;
    padding: 4px 6px;
    font-size: 12px;
    vertical-align: middle;
}
table.tbl-nested tr[data-status="critical"] {
    background: #fee2e2;
}
table.tbl-nested tr[data-status="substantial"] {
    background: #fef3c7;
}
table.tbl-nested tr[data-status="informational"] {
    background: #dbeafe;
}
table.tbl-nested tr[data-status="normal"] {
    background: #ffffff;
}

.tbl-nested-title {
    font-weight: 600;
    color: #475569;
    margin-bottom: 6px;
    margin-top: 6px;
    font-size: 12px;
}

/* Заголовок секции 6 (скрыт — выводится в <summary> родительского <details>) */
.section-6-title {
    display: none;
}

